<script setup lang="ts">
definePageMeta({ middleware: 'auth' })
const route = useRoute(); const { data, refresh } = await useFetch<any>(`/api/orders/${route.params.id}`)
const statusText: Record<string, string> = { PENDING: '等大厨接单', ACCEPTED: '大厨已接单', PREPARING: '热锅进行中', COMPLETED: '已经开饭', REJECTED: '本次未接单', CANCELLED: '已取消' }
const ratingText: Record<string, string> = { GOOD: '好评', NEUTRAL: '中评', BAD: '差评' }
const ratingMessage = ref(''); const ratingError = ref(''); const ratingSaving = ref(false)
async function rate(rating: 'GOOD' | 'NEUTRAL' | 'BAD') {
  ratingSaving.value = true; ratingError.value = ''
  try { await $fetch(`/api/orders/${route.params.id}/rating`, { method: 'PUT', body: { rating } }); ratingMessage.value = '收到啦！大厨会继续努力投喂你 🍳'; await refresh() }
  catch (error: any) { ratingError.value = error?.data?.statusMessage || error?.data?.message || '评价没有送出去，再试一次吧' }
  finally { ratingSaving.value = false }
}
</script>

<template><main class="mx-auto min-h-screen max-w-lg p-5 pb-28"><NuxtLink to="/orders" class="font-black underline">← 返回订单</NuxtLink><article v-if="data?.order" class="mt-5"><section class="sticker-card bg-lemon p-6"><p class="font-black">订单 #{{ data.order.id }}</p><h1 class="mt-2 text-3xl font-black">{{ statusText[data.order.status] }}</h1><p class="mt-3 font-semibold">{{ data.order.scheduledDate }} · {{ data.order.mealSlot === 'LUNCH' ? '午餐' : '晚餐' }}</p><p v-if="data.order.note" class="mt-3 rounded-xl bg-white/70 p-3 font-semibold">“{{ data.order.note }}”</p></section><section class="sticker-card mt-6 p-5"><h2 class="text-xl font-black">点了这些</h2><div v-for="item in data.order.items" :key="item.id" class="mt-3 flex items-center justify-between border-b border-ink/15 pb-3 last:border-0"><strong>{{ item.dishName }}</strong><span class="font-black">× {{ item.quantity }}</span></div></section><section v-if="data.order.status === 'COMPLETED'" class="sticker-card mt-6 bg-peach p-5"><h2 class="text-xl font-black">这顿饭吃得怎么样？</h2><p class="mt-2 font-semibold text-ink/65">给大厨一个小反馈，下次继续精准投喂～</p><div class="mt-4 grid grid-cols-3 gap-2"><button v-for="item in [{ key: 'GOOD', label: '好评', emoji: '🥰' }, { key: 'NEUTRAL', label: '中评', emoji: '🙂' }, { key: 'BAD', label: '差评', emoji: '🥺' }]" :key="item.key" class="rounded-2xl border-2 border-ink bg-white px-2 py-3 font-black transition hover:-translate-y-0.5" :class="data.order.rating?.rating === item.key ? 'bg-lemon' : ''" :disabled="ratingSaving" @click="rate(item.key as 'GOOD' | 'NEUTRAL' | 'BAD')"><span class="block text-2xl">{{ item.emoji }}</span>{{ item.label }}</button></div><p v-if="data.order.rating" class="mt-3 text-center font-black">当前评价：{{ ratingText[data.order.rating.rating] }} · 可以重新选择</p><p v-if="ratingMessage" class="mt-3 text-center font-bold text-green-700">{{ ratingMessage }}</p><p v-if="ratingError" class="mt-3 text-center font-bold text-danger">{{ ratingError }}</p></section><section v-if="data.order.history.length" class="sticker-card mt-6 bg-mint p-5"><h2 class="text-xl font-black">进度小广播</h2><ol class="mt-4 space-y-3"><li v-for="item in data.order.history" :key="item.id" class="flex gap-3"><span class="mt-1 size-3 shrink-0 rounded-full border-2 border-ink bg-peach"></span><div><strong>{{ statusText[item.toStatus] }}</strong><p v-if="item.note" class="text-sm font-semibold text-ink/60">{{ item.note }}</p></div></li></ol></section></article></main></template>
